package chess

import (
	"math/rand/v2"
	"testing"
)

func TestSearchTagGeometryInitialization(t *testing.T) {
	for target := A1; target <= H8; target++ {
		g := searchTagGeometry[target]
		if g.orthogonal != hvAttack(0, target) || g.diagonal != diaAttack(0, target) {
			t.Fatal("geometry initialization/alignment", target)
		}
		for origin := A1; origin <= H8; origin++ {
			dx, dy := int(target.File())-int(origin.File()), int(target.Rank())-int(origin.Rank())
			if dx < 0 {
				dx = -dx
			}
			if (g.pawnOrigins[White]&bbForSquare(origin) != 0) != (dx == 1 && dy == 1) || (g.pawnOrigins[Black]&bbForSquare(origin) != 0) != (dx == 1 && dy == -1) {
				t.Fatal("pawn checking origin", target, origin)
			}
		}
	}
}

func TestSearchTagsMatchEveryPseudoLegalCandidate(t *testing.T) {
	checked := 0
	check := func(p *Position) {
		t.Helper()
		fen, hash := p.String(), p.ZobristHash()
		for _, classify := range []bool{false, true} {
			c := newSearchTagContext(p, classify)
			allowed := ^p.board.whiteSqs
			if p.turn == Black {
				allowed = ^p.board.blackSqs
			}
			for from := A1; from <= H8; from++ {
				piece := p.board.Piece(from)
				if piece == NoPiece || piece.Color() != p.turn {
					continue
				}
				toSet := bbForPossibleMoves(p, piece.Type(), from) & allowed
				for to := A1; to <= H8; to++ {
					if toSet&bbForSquare(to) == 0 {
						continue
					}
					promos := []PieceType{NoPieceType}
					if (piece == WhitePawn && to.Rank() == Rank8) || (piece == BlackPawn && to.Rank() == Rank1) {
						promos = promoPieceTypes[:]
					}
					for _, promo := range promos {
						m := Move{s1: from, s2: to, promo: promo}
						got, want := c.tags(m), searchMoveTags(m, p, classify)
						if got != want {
							t.Fatal("pseudo tags", fen, m.String(), classify, got, want)
						}
						checked++
					}
				}
			}
			for _, m := range castleMoves(p) {
				if got, want := c.tags(m), searchMoveTags(m, p, classify); got != want {
					t.Fatal("castle tags", fen, m, got, want)
				}
				checked++
			}
		}
		if p.String() != fen || p.ZobristHash() != hash {
			t.Fatal("tag context mutated parent")
		}
	}
	for _, fen := range []string{
		StartingPosition().String(),
		"r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1",
		"r3k2r/8/8/8/8/8/8/R3K2R b KQkq - 0 1",
		"4k3/8/8/3pP3/8/8/8/4K3 w - d6 0 1",
		"4k3/8/8/8/3Pp3/8/8/4K3 b - d3 0 1",
		"k3r3/8/8/3pP3/8/8/8/4K3 w - d6 0 1",
		"8/8/8/R2pP2k/8/8/8/K7 w - d6 0 1",
		"r6k/1P6/8/8/8/8/8/7K w - - 0 1",
		"7k/8/8/8/8/8/1p6/R6K b - - 0 1",
		"4k3/8/8/8/8/8/4B3/4R2K w - - 0 1",
		"4k3/8/8/8/8/8/8/K3R3 w - - 0 1",
		"7r/8/8/8/8/6k1/8/6BK w - - 0 1",
		"7k/6Q1/5K2/8/8/8/8/8 b - - 0 1",
		"7k/5K2/6Q1/8/8/8/8/8 b - - 0 1",
		"8/8/8/8/8/8/P7/7k w - - 0 1",
		"8/8/8/8/8/8/P7/7K w - - 0 1",
	} {
		p, err := decodeFEN(fen)
		if err != nil {
			t.Fatal(err)
		}
		check(p)
	}
	rng := rand.New(rand.NewPCG(22, 2222))
	p := StartingPosition()
	for i := 0; i < 1500; i++ {
		check(p)
		moves := p.ValidMoves()
		if len(moves) == 0 || i%100 == 99 {
			p = StartingPosition()
		} else {
			m := moves[rng.IntN(len(moves))]
			p = p.Update(&m)
		}
	}
	if checked < 50000 {
		t.Fatal("insufficient pseudo tags", checked)
	}
	t.Log("Pseudo-legal tags matched:", checked)
}

func TestSearchTagsQuietAndConservativeControls(t *testing.T) {
	p := StartingPosition()
	c := newSearchTagContext(p, true)
	quiet := Move{s1: B2, s2: B3}
	if c.ownRays&bbForSquare(B2) != 0 || c.otherRays&bbForSquare(B2) != 0 || c.checkingTargets[Pawn]&bbForSquare(B3) != 0 || c.otherCheck || p.inCheck {
		t.Fatal("quiet positive control no longer rules out both tests")
	}
	if c.tags(quiet) != 0 {
		t.Fatal("quiet control tags")
	}
	for _, x := range []struct {
		fen      string
		from, to Square
		want     MoveTag
	}{
		{"k3r3/8/8/8/8/8/4R3/4K3 w - - 0 1", E2, F2, inCheck},
		{"4k3/8/8/8/8/8/4B3/4R2K w - - 0 1", E2, F3, Check},
		{"k3r3/8/8/3pP3/8/8/8/4K3 w - d6 0 1", E5, D6, inCheck | EnPassant},
		{"8/8/8/R2pP2k/8/8/8/K7 w - d6 0 1", E5, D6, Check | EnPassant},
	} {
		p, err := decodeFEN(x.fen)
		if err != nil {
			t.Fatal(err)
		}
		c := newSearchTagContext(p, true)
		m := Move{s1: x.from, s2: x.to}
		if got := c.tags(m); got&x.want != x.want || got != searchMoveTags(m, p, true) {
			t.Fatal("conservative control", x.fen, got, x.want)
		}
	}
}

